{
  "items": [
    {
      "name": "ENNReal.rpow_add",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.NNReal",
      "kind": "theorem",
      "type": "∀ {x : ENNReal} (y z : ℝ), x ≠ 0 → x ≠ ⊤ → x ^ (y + z) = x ^ y * x ^ z"
    },
    {
      "name": "Real.rpow_add",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, 0 < x → ∀ (y z : ℝ), x ^ (y + z) = x ^ y * x ^ z"
    },
    {
      "name": "ENNReal.zpow_add",
      "module_name": "Mathlib.Data.ENNReal.Inv",
      "kind": "theorem",
      "type": "∀ {x : ENNReal}, x ≠ 0 → x ≠ ⊤ → ∀ (m n : ℤ), x ^ (m + n) = x ^ m * x ^ n"
    },
    {
      "name": "ENNReal.rpow_add_of_nonneg",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.NNReal",
      "kind": "theorem",
      "type": "∀ {x : ENNReal} (y z : ℝ), 0 ≤ y → 0 ≤ z → x ^ (y + z) = x ^ y * x ^ z"
    },
    {
      "name": "Real.rpow_add'",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y z : ℝ}, 0 ≤ x → y + z ≠ 0 → x ^ (y + z) = x ^ y * x ^ z"
    }
  ]
}
